mapper.sql:
r.tenant_id = #{q.tenantId}
AND r.hotel_id = #{q.hotelId}

    AND r.status IN

        #{status}



    AND r.source_type = #{q.sourceType}


    AND r.reservation_no LIKE #{q.reservationNoPrefix} || '%' ESCAPE '\'


    AND EXISTS (
        SELECT 1
        FROM reservation_line l
        JOIN room_occupancy o ON o.line_id = l.id AND o.kind = 'RESERVATION'
        JOIN physical_room pr ON pr.id = o.room_id AND pr.hotel_id = o.hotel_id
        WHERE l.reservation_id = r.id
          AND pr.code = #{q.roomCode}
    )


    AND EXISTS (
        SELECT 1
        FROM reservation_line l
        WHERE l.reservation_id = r.id
          AND l.planned_range && daterange(#{q.stayFrom}::date, #{q.stayTo}::date, '[)')
    )

mapper.select:
SELECT o.line_id, o.room_id, pr.code AS room_code, o.status AS occupancy_status
FROM room_occupancy o
JOIN physical_room pr ON pr.id = o.room_id AND pr.hotel_id = o.hotel_id
WHERE o.tenant_id = #{tenantId}
  AND o.hotel_id = #{hotelId}
  AND o.reservation_id = #{reservationId}
  AND o.kind = 'RESERVATION'
ORDER BY o.line_id, o.created_at
